create extension if not exists pgcrypto;
create table if not exists public.staff (id uuid primary key default gen_random_uuid(), name_uz text default '',name_ru text default '',name_en text default '',name_zh text default '',role_uz text default '',role_ru text default '',role_en text default '',role_zh text default '',phone text default '',email text default '',image_url text default '',sort_order integer default 0,is_published boolean default true,created_at timestamptz default now());
create table if not exists public.documents (id uuid primary key default gen_random_uuid(),title_uz text default '',title_ru text default '',title_en text default '',title_zh text default '',file_type text default 'PDF',document_date date default current_date,file_url text default '',is_published boolean default true,created_at timestamptz default now());
create table if not exists public.media_items (id uuid primary key default gen_random_uuid(),title_uz text default '',title_ru text default '',title_en text default '',title_zh text default '',description_uz text default '',description_ru text default '',description_en text default '',description_zh text default '',media_type text default 'image',media_url text default '',thumbnail_url text default '',is_published boolean default true,created_at timestamptz default now());
create table if not exists public.map_objects (id uuid primary key default gen_random_uuid(),title_uz text default '',title_ru text default '',title_en text default '',title_zh text default '',description_uz text default '',description_ru text default '',description_en text default '',description_zh text default '',latitude double precision default 37.2242,longitude double precision default 67.2783,address text default '',category text default '',is_published boolean default true,created_at timestamptz default now());

do $$ declare t text; begin foreach t in array array['staff','documents','media_items','map_objects'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists "Public read %s" on public.%I',t,t); execute format('create policy "Public read %s" on public.%I for select using (is_published=true or auth.role()=''authenticated'')',t,t); execute format('drop policy if exists "Admin manage %s" on public.%I',t,t); execute format('create policy "Admin manage %s" on public.%I for all to authenticated using (true) with check (true)',t,t); execute format('grant select on public.%I to anon',t); execute format('grant all on public.%I to authenticated',t); end loop; end $$;
